.target sm_89
.address_size 64

.visible .entry conv2d_nchw_f32(
    .param .u64 in_ptr,
    .param .u64 weight_ptr,
    .param .u64 bias_ptr,
    .param .u64 out_ptr,
    .param .s32 N,
    .param .s32 Cin,
    .param .s32 H,
    .param .s32 W,
    .param .s32 Cout,
    .param .s32 KH,
    .param .s32 KW,
    .param .s32 Hout,
    .param .s32 Wout,
    .param .s32 stride_h,
    .param .s32 pad_h,
    .param .s32 pad_w,
    .param .s32 dil_h,
    .param .s32 dil_w,
    .param .s32 has_bias
)
{
    .reg .pred %p_oob_x, %p_oob_y, %p_oob_z, %p_kh, %p_ic, %p_kw;
    .reg .pred %p_ih_lo, %p_ih_hi, %p_ih_bad, %p_iw_lo, %p_iw_hi, %p_iw_bad, %p_nobias;
    .reg .b32 %r_bx, %r_by, %r_bz, %r_tx, %r_ty, %r_tz;
    .reg .b32 %r_ow, %r_oh, %r_z, %r_n, %r_oc, %r_total;
    .reg .b32 %r_N, %r_Cin, %r_H, %r_W, %r_Cout, %r_KH, %r_KW, %r_Hout, %r_Wout;
    .reg .b32 %r_stride, %r_pad_h, %r_pad_w, %r_dil_h, %r_dil_w, %r_has_bias;
    .reg .b32 %r_kh, %r_kw, %r_ic, %r_ih, %r_iw, %r_tmp, %r_in_base, %r_w_base, %r_in_idx, %r_w_idx, %r_out_idx;
    .reg .b64 %rd_in, %rd_w, %rd_b, %rd_out, %rd_off, %rd_ptr;
    .reg .f32 %f_acc, %f_x, %f_w, %f_b;

    ld.param.u64 %rd_in, [in_ptr];
    ld.param.u64 %rd_w, [weight_ptr];
    ld.param.u64 %rd_b, [bias_ptr];
    ld.param.u64 %rd_out, [out_ptr];
    ld.param.s32 %r_N, [N];
    ld.param.s32 %r_Cin, [Cin];
    ld.param.s32 %r_H, [H];
    ld.param.s32 %r_W, [W];
    ld.param.s32 %r_Cout, [Cout];
    ld.param.s32 %r_KH, [KH];
    ld.param.s32 %r_KW, [KW];
    ld.param.s32 %r_Hout, [Hout];
    ld.param.s32 %r_Wout, [Wout];
    ld.param.s32 %r_stride, [stride_h];
    ld.param.s32 %r_pad_h, [pad_h];
    ld.param.s32 %r_pad_w, [pad_w];
    ld.param.s32 %r_dil_h, [dil_h];
    ld.param.s32 %r_dil_w, [dil_w];
    ld.param.s32 %r_has_bias, [has_bias];

    mov.u32 %r_bx, %ctaid.x;
    mov.u32 %r_by, %ctaid.y;
    mov.u32 %r_bz, %ctaid.z;
    mov.u32 %r_tx, %tid.x;
    mov.u32 %r_ty, %tid.y;
    mov.u32 %r_tz, %tid.z;

    mov.u32 %r_tmp, %ntid.x;
    mad.lo.s32 %r_ow, %r_bx, %r_tmp, %r_tx;
    mov.u32 %r_tmp, %ntid.y;
    mad.lo.s32 %r_oh, %r_by, %r_tmp, %r_ty;
    mov.u32 %r_tmp, %ntid.z;
    mad.lo.s32 %r_z, %r_bz, %r_tmp, %r_tz;

    setp.ge.s32 %p_oob_x, %r_ow, %r_Wout;
    @%p_oob_x bra %L_done;
    setp.ge.s32 %p_oob_y, %r_oh, %r_Hout;
    @%p_oob_y bra %L_done;
    mul.lo.s32 %r_total, %r_N, %r_Cout;
    setp.ge.s32 %p_oob_z, %r_z, %r_total;
    @%p_oob_z bra %L_done;

    div.s32 %r_n, %r_z, %r_Cout;
    rem.s32 %r_oc, %r_z, %r_Cout;

    mov.f32 %f_acc, 0f00000000;
    mov.b32 %r_kh, 0;

