    setp.ge.s32 %p_kh, %r_kh, %r_KH;
    @%p_kh bra %L_store;

    mul.lo.s32 %r_ih, %r_oh, %r_stride;
    sub.s32 %r_ih, %r_ih, %r_pad_h;
    mad.lo.s32 %r_ih, %r_kh, %r_dil_h, %r_ih;
    setp.lt.s32 %p_ih_lo, %r_ih, 0;
    setp.ge.s32 %p_ih_hi, %r_ih, %r_H;
    or.pred %p_ih_bad, %p_ih_lo, %p_ih_hi;
    @%p_ih_bad bra %L_next_kh;

    mov.b32 %r_ic, 0;
%L_ic:
    setp.ge.s32 %p_ic, %r_ic, %r_Cin;
    @%p_ic bra %L_next_kh;

    mul.lo.s32 %r_tmp, %r_n, %r_Cin;
    add.s32 %r_tmp, %r_tmp, %r_ic;
    mul.lo.s32 %r_tmp, %r_tmp, %r_H;
    add.s32 %r_tmp, %r_tmp, %r_ih;
    mul.lo.s32 %r_in_base, %r_tmp, %r_W;

    mul.lo.s32 %r_tmp, %r_oc, %r_Cin;
    add.s32 %r_tmp, %r_tmp, %r_ic;
    mul.lo.s32 %r_tmp, %r_tmp, %r_KH;
    add.s32 %r_tmp, %r_tmp, %r_kh;
    mul.lo.s32 %r_w_base, %r_tmp, %r_KW;

    mov.b32 %r_kw, 0;
%L_kw:
    setp.ge.s32 %p_kw, %r_kw, %r_KW;
    @%p_kw bra %L_next_ic;

    mul.lo.s32 %r_iw, %r_ow, %r_stride;
    sub.s32 %r_iw, %r_iw, %r_pad_w;
    mad.lo.s32 %r_iw, %r_kw, %r_dil_w, %r_iw;
    setp.lt.s32 %p_iw_lo, %r_iw, 0;
    setp.ge.s32 %p_iw_hi, %r_iw, %r_W;
    or.pred %p_iw_bad, %p_iw_lo, %p_iw_hi;
    @%p_iw_bad bra %L_next_kw;

