    cvt.u64.u32 %rd_off, %r_in_idx;
    shl.b64 %rd_off, %rd_off, 2;
    add.s64 %rd_ptr, %rd_in, %rd_off;
    ld.global.f32 %f_x, [%rd_ptr];

