    shl.b64 %rd_off, %rd_off, 2;
    add.s64 %rd_ptr, %rd_w, %rd_off;
    ld.global.f32 %f_w, [%rd_ptr];

    fma.rn.f32 %f_acc, %f_x, %f_w, %f_acc;

