    setp.eq.s32 %p_nobias, %r_has_bias, 0;
    @%p_nobias bra %L_write;
    cvt.u64.u32 %rd_off, %r_oc;
    shl.b64 %rd_off, %rd_off, 2;
    add.s64 %rd_ptr, %rd_b, %rd_off;
    ld.global.f32 %f_b, [%rd_ptr];
    add.f32 %f_acc, %f_acc, %f_b;

%L_write:
    mul.lo.s32 %r_tmp, %r_n, %r_Cout;
    add.s32 %r_tmp, %r_tmp, %r_oc;
    mul.lo.s32 %r_tmp, %r_tmp, %r_Hout;
    add.s32 %r_tmp, %r_tmp, %r_oh;
    mul.lo.s32 %r_out_idx, %r_tmp, %r_Wout;
    add.s32 %r_out_idx, %r_out_idx, %r_ow;
    cvt.u64.u32 %rd_off, %r_out_idx;
    shl.b64 %rd_off, %rd_off, 2;
    add.s64 %rd_ptr, %rd_out, %rd_off;
    st.global.f32 [%rd_ptr], %f_acc;

