def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module


def validate_generated_code():
    _get_ptx_module().function("conv2d_nchw_f32")


