    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: int = 1, padding: tuple = (0, 0), dilation: tuple = (1, 1), bias: bool = False):
        super().__init__()
        self.conv2d = nn.Conv2d(in_channels, out_channels, kernel_size, stride=stride, padding=padding, dilation=dilation, bias=bias)
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        n, cin, h, w = x.shape
        kh, kw = self.kernel_size
        ph, pw = self.padding
        dh, dw = self.dilation
        sh = self.stride
        hout = (h + 2 * ph - dh * (kh - 1) - 1) // sh + 1
        wout = (w + 2 * pw - dw * (kw - 1) - 1) // sh + 1

        y = torch.empty((n, self.out_channels, hout, wout), device=x.device, dtype=x.dtype)
        module = _get_ptx_module()
        weight = self.conv2d.weight
        bias = self.conv2d.bias if self.conv2d.bias is not None else weight
        has_bias = 1 if self.conv2d.bias is not None else 0

        block = (32, 8, 1)
        grid = ((wout + block[0] - 1) // block[0], (hout + block[1] - 1) // block[1], n * self.out_channels)
        module.launch(
            "conv2d_nchw_f32",
            grid=grid,
            block=block,
            arguments=[
                x,
                weight,
                bias,
                y,
                i32(n),
                i32(cin),
                i32(h),
                i32(w),
                i32(self.out_channels),
                i32(kh),
                i32(kw),
                i32(hout),
                i32(wout),
                i32(sh),
                i32(ph),
                i32(pw),
                i32(dh),
                i32(dw),
                i32(has_bias),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return y

